      </Card>
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Card } from '../components/Card';
import { db, makeClientId } from '../db/offlineDb';
import { useVoiceRecognition } from '../hooks/useVoiceRecognition';
import { useTextToSpeech } from '../hooks/useTextToSpeech';
import { useTranslation } from 'react-i18next';
import { Mic, MicOff, Volume2, ChevronLeft, Zap } from 'lucide-react';

const OPTIONS_BASE = [
  { value: 0, key: '0', voiceTokens: ['never', 'no', 'zero', 'कभी नहीं', 'नहीं'] },
  { value: 1, key: '1', voiceTokens: ['hardly', 'not often', 'rarely', 'अक्सर नहीं'] },
  { value: 2, key: '2', voiceTokens: ['sometimes', 'कभी-कभी', 'कभी'] },
  { value: 3, key: '3', voiceTokens: ['yes', 'often', 'always', 'हाँ', 'अधिकतर'] },
];

export const PPDScreening: React.FC = () => {
  const { t } = useTranslation();
  const questions: string[] = t('ppd.questions', { returnObjects: true }) as string[];
  const { listen, stop: stopListen, isListening, transcript, clearTranscript } = useVoiceRecognition();
  const { speak, stop: stopSpeak } = useTextToSpeech();

  const [currentQ, setCurrentQ] = useState(0);
  const [answers, setAnswers] = useState<number[]>(Array(10).fill(-1));
  const [status, setStatus] = useState('');
  const [result, setResult] = useState<{ score: number; risk: string; message: string } | null>(null);
  const [slideDir, setSlideDir] = useState<'left' | 'right'>('left');
  const hasSpokenIntro = useRef(false);

  // Voice intro on first mount
  useEffect(() => {
    if (!hasSpokenIntro.current) {
      hasSpokenIntro.current = true;
      setTimeout(() => {
        speak(t('ppd.voice_instruction'), () => {
          if (questions[0]) readQuestion(0);
        });
      }, 600);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const readQuestion = useCallback((idx: number) => {
    stopSpeak();
    const optionsText = OPTIONS_BASE.map(o => t(`ppd.options.${o.key}`)).join('. ');
    speak(
      `${t('ppd.question_x_of_10', { current: idx + 1 })}. ${questions[idx]}. ${optionsText}.`,
      () => listen()
    );
  }, [speak, stopSpeak, listen, questions, t]);

  // Read each new question
  useEffect(() => {
    if (currentQ < 10 && !result && hasSpokenIntro.current) {
      const timer = setTimeout(() => readQuestion(currentQ), 300);
      return () => clearTimeout(timer);
    }
  }, [currentQ, result, readQuestion]);

  // Voice answer matching
  useEffect(() => {
    if (!transcript || currentQ >= 10 || result) return;
    const lower = transcript.toLowerCase();
    let matched = false;
    for (const opt of OPTIONS_BASE) {
      if (opt.voiceTokens.some(tok => lower.includes(tok))) {
        handleSelect(opt.value);
        matched = true;
        break;
      }
    }
    if (!matched) {
      speak(`${t('common.error')}. ${OPTIONS_BASE.map(o => t(`ppd.options.${o.key}`)).join(', ')}.`, () => listen());
    }
    clearTranscript();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [transcript]);

  const handleSelect = useCallback((val: number) => {
    stopListen();
    const newAnswers = [...answers];
    newAnswers[currentQ] = val;
    setAnswers(newAnswers);

    speak(`${t(`ppd.options.${val}`)}`, () => {
      if (currentQ < 9) {
        setSlideDir('left');
        setCurrentQ(q => q + 1);
      } else {
        finalizeResult(newAnswers);
      }
    });
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [answers, currentQ, stopListen, speak, t]);

  const handlePrevious = () => {
    if (currentQ > 0) {
      setSlideDir('right');
      setCurrentQ(q => q - 1);
    }
  };

  const finalizeResult = async (finalAnswers: number[]) => {
    if (finalAnswers.includes(-1)) return;
    const total_score = finalAnswers.reduce((a, b) => a + b, 0);
    let risk_level: 'low' | 'medium' | 'high' = 'low';
    let referral_message = t('ppd.result_low');

    if (total_score >= 13) { risk_level = 'high'; referral_message = t('ppd.result_high'); }
    else if (total_score >= 10) { risk_level = 'medium'; referral_message = t('ppd.result_medium'); }

    setResult({ score: total_score, risk: risk_level, message: referral_message });
    speak(`${t('ppd.score')}: ${total_score}. ${t('ppd.risk')}: ${t(`ppd.result_${risk_level}`)}. ${referral_message}`);

    try {
      await db.unsyncedPPD.add({
        clientId: makeClientId(),
        clientTimestamp: new Date().toISOString(),
        epds_answers: finalAnswers,
        total_score,
        risk_level,
        referral_message,
      });
      setStatus(t('common.saved_offline'));
      setTimeout(() => {
        setAnswers(Array(10).fill(-1));
        setResult(null);
        setCurrentQ(0);
        setStatus('');
        hasSpokenIntro.current = false;
      }, 8000);
    } catch (e) {
      console.error(e);
      setStatus(t('common.error'));
    }
  };

  const riskConfig = {
    high:   { border: 'border-red-200 bg-red-50',     text: 'text-red-700',     score: 'text-red-600' },
    medium: { border: 'border-orange-200 bg-orange-50',text: 'text-orange-700', score: 'text-orange-600' },
    low:    { border: 'border-emerald-200 bg-emerald-50', text: 'text-emerald-700', score: 'text-emerald-600' },
  };

  if (result) {
    const cfg = riskConfig[result.risk as keyof typeof riskConfig];
    return (
      <div className="space-y-4 pb-4 animate-fade-in">
        <h2 className="text-2xl font-extrabold text-gray-900">{t('ppd.full_title')}</h2>
        <Card className={`text-center py-10 border-2 ${cfg.border} animate-bounce-in`}>
          {/* Score ring */}
          <div className="relative w-28 h-28 mx-auto mb-6">
            <svg className="w-full h-full -rotate-90" viewBox="0 0 100 100">
              <circle cx="50" cy="50" r="42" fill="none" stroke="#e5e7eb" strokeWidth="8" />
              <circle
                cx="50" cy="50" r="42" fill="none"
                stroke={result.risk === 'high' ? '#ef4444' : result.risk === 'medium' ? '#f59e0b' : '#10b981'}
                strokeWidth="8"
                strokeDasharray={`${(result.score / 30) * 264} 264`}
                strokeLinecap="round"
                className="transition-all duration-1000"
              />
            </svg>
            <div className="absolute inset-0 flex flex-col items-center justify-center">
              <h3 className={`font-black text-4xl ${cfg.score}`}>{result.score}</h3>
              <p className="text-xs text-gray-400 font-bold">/30</p>
            </div>
          </div>
          <p className={`text-xl font-black mb-2 uppercase tracking-wide ${cfg.text}`}>
            {result.risk} {t('ppd.risk')}
          </p>
          <p className="text-gray-700 font-medium px-4 mb-4 text-sm leading-relaxed">{result.message}</p>
          {status && (
            <div className="p-3 bg-white/60 border border-white rounded-xl text-sm font-bold mx-4 text-emerald-700">
              {status}
            </div>
          )}
          {/* Re-read result */}
          <button
            onClick={() => speak(`${t('ppd.score')}: ${result.score}. ${result.message}`)}
            className="mt-4 flex items-center gap-2 mx-auto px-4 py-2 rounded-full bg-white/80 text-primary font-bold text-sm shadow-sm"
          >
            <Volume2 size={16} /> {t('common.tap_to_hear')}
          </button>

          {/* EPDS tip */}
          <div className="mx-4 mt-4 sci-ref-card text-left">
            <p className="text-xs text-gray-600 leading-relaxed"><span className="font-bold text-primary">EPDS: </span>{t('ppd.epds_tip')}</p>
          </div>
        </Card>
      </div>
    );
  }

  const progress = (currentQ / 10) * 100;

  return (
    <div className="space-y-4 pb-4 animate-fade-in">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-extrabold text-gray-900 leading-tight">{t('ppd.title')}</h2>
          <p className="text-sm font-bold text-primary">{t('ppd.question_x_of_10', { current: currentQ + 1 })}</p>
        </div>
        <button
          id="ppd-replay-btn"
          onClick={() => readQuestion(currentQ)}
          className="p-3 rounded-full shadow-sm hover:scale-105 active:scale-95 transition-all"
          style={{ background: 'rgba(139,92,246,0.1)', color: '#8b5cf6' }}
          aria-label="Replay question"
        >
          <Volume2 size={22} />
        </button>
      </div>

      <Card className="animate-slide-up">
        {/* Voice bar */}
        <div className="mb-5 flex justify-between items-center bg-gray-50/50 p-4 rounded-xl border border-gray-100">
          <span className="text-gray-700 font-medium text-sm">{t('ppd.use_voice_answer')}</span>
          <button
            id="ppd-mic-btn"
            onClick={isListening ? stopListen : listen}
            className={isListening ? 'btn-voice-active' : 'btn-voice-idle'}
            aria-label="Voice input"
          >
            {isListening
              ? <div className="voice-wave"><span/><span/><span/><span/><span/></div>
              : <Mic size={22} className="text-white" />
            }
          </button>
        </div>

        {isListening && (
          <div className="voice-hint mb-4 animate-fade-in text-xs">
            🎤 {t('ppd.voice_instruction')}
          </div>
        )}

        {/* Progress bar */}
        <div className="mb-6">
          <div className="flex justify-between items-center mb-1">
            <span className="text-xs font-bold text-gray-400">{t('ppd.question_x_of_10', { current: currentQ + 1 })}</span>
            <span className="text-xs font-bold text-primary">{Math.round(progress)}%</span>
          </div>
          <div className="h-2.5 bg-gray-100 rounded-full overflow-hidden">
            <div
              className="h-full rounded-full transition-all duration-500"
              style={{ width: `${progress}%`, background: 'linear-gradient(90deg, #8b5cf6, #6367FF)' }}
            />
          </div>
        </div>

        {/* Question */}
        <div
          key={`q-${currentQ}`}
          className={`mb-8 min-h-[100px] flex items-center justify-center p-6 rounded-2xl border border-primary/20 ${slideDir === 'left' ? 'animate-slide-left' : 'animate-slide-right'}`}
          style={{ background: 'linear-gradient(135deg, rgba(99,103,255,0.04), rgba(139,92,246,0.06))' }}
        >
          <p className="text-xl font-black text-center text-gray-800 leading-snug">{questions[currentQ]}</p>
        </div>

        {/* Options */}
        <div className="space-y-3">
          {OPTIONS_BASE.map((opt, oi) => (
            <button
              key={opt.value}
              id={`ppd-opt-${opt.value}`}
              onClick={() => handleSelect(opt.value)}
              className={`w-full p-4 rounded-2xl border-2 font-bold text-base text-left transition-all flex justify-between items-center active:scale-95 ${
                answers[currentQ] === opt.value
                  ? 'border-violet-400 bg-violet-50 text-violet-700 shadow-md'
                  : 'border-gray-100 bg-white/60 text-gray-700 hover:border-primary/40 hover:bg-primary/5'
              }`}
              style={{ animationDelay: `${oi * 60}ms` }}
            >
              <span>{t(`ppd.options.${opt.key}`)}</span>
              <button
                onClick={e => { e.stopPropagation(); speak(t(`ppd.options.${opt.key}`)); }}
                className="p-2 text-primary hover:bg-primary/10 rounded-full transition-colors flex-shrink-0"
                aria-label="Read option"
              >
                <Volume2 size={18} />
              </button>
            </button>
          ))}
        </div>

        {/* Previous button */}
        {currentQ > 0 && (
          <button
            id="ppd-prev-btn"
            onClick={handlePrevious}
            className="mt-5 flex items-center gap-2 text-sm font-bold text-gray-500 hover:text-primary transition-colors"
          >
            <ChevronLeft size={16} /> {t('ppd.prev_question')}
          </button>
        )}

        {/* EPDS scientific reference */}
        <div className="mt-5 sci-ref-card flex items-start gap-2">
          <Zap size={14} className="text-primary flex-shrink-0 mt-0.5" />
          <p className="text-xs text-gray-600 font-medium leading-relaxed">{t('ppd.epds_tip')}</p>
        </div>
      </Card>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Card } from '../components/Card';
import { db } from '../db/offlineDb';
import { syncData } from '../services/api';
import { useTranslation } from 'react-i18next';
import { useTextToSpeech } from '../hooks/useTextToSpeech';
import { CloudUpload, CheckCircle, AlertCircle, Database, RefreshCw, Wifi, CloudOff, Cloud, Volume2 } from 'lucide-react';
import { useOnlineStatus } from '../hooks/useOnlineStatus';

export const SyncData: React.FC = () => {
  const { t } = useTranslation();
  const { speak } = useTextToSpeech();
  const isOnline = useOnlineStatus();
  const [syncing, setSyncing] = useState(false);
  const [status, setStatus] = useState<'idle' | 'success' | 'error' | 'none'>('idle');
  const [counts, setCounts] = useState({ anemia: 0, ppd: 0, alerts: 0 });

  const refreshPendingCount = useCallback(async () => {
    const anemia = await db.unsyncedAnemia.count();
    const ppd = await db.unsyncedPPD.count();
    const alerts = await db.unsyncedAlerts.count();
    setCounts({ anemia, ppd, alerts });
  }, []);

  useEffect(() => { refreshPendingCount(); }, [refreshPendingCount]);

  const totalPending = counts.anemia + counts.ppd + counts.alerts;

  const handleSync = async () => {
    setSyncing(true);
    setStatus('idle');
    try {
      const anemia = (await db.unsyncedAnemia.toArray()).map(({ id, ...rest }) => rest);
      const ppd = (await db.unsyncedPPD.toArray()).map(({ id, ...rest }) => rest);
      const alerts = (await db.unsyncedAlerts.toArray()).map(({ id, ...rest }) => rest);

      if (anemia.length === 0 && ppd.length === 0 && alerts.length === 0) {
        setStatus('none');
        speak(t('sync.no_data'));
        setSyncing(false);
        return;
      }

      await syncData({ anemia, ppd, alerts });
      await db.unsyncedAnemia.clear();
      await db.unsyncedPPD.clear();
      await db.unsyncedAlerts.clear();

      setStatus('success');
      speak(t('sync.success'));
      setCounts({ anemia: 0, ppd: 0, alerts: 0 });
      setTimeout(() => setStatus('idle'), 5000);
    } catch (e) {
      console.error(e);
      setStatus('error');
      speak(t('common.error'));
    } finally {
      setSyncing(false);
    }
  };

  const speakStatus = () => {
    const statusText = totalPending > 0
      ? t('sync.pending', { count: totalPending })
      : t('sync.all_synced');
    const connText = isOnline ? t('sync.connected') : t('sync.no_internet');
    speak(`${statusText}. ${connText}.`);
  };

  return (
    <div className="space-y-4 pb-4 animate-fade-in">
      <div className="flex items-start justify-between">
        <div>
          <h2 className="text-2xl font-extrabold text-gray-900">{t('sync.title')}</h2>
          <p className="text-sm text-gray-400 font-medium">{t('sync.subtitle')}</p>
        </div>
        <button
          id="sync-voice-btn"
          onClick={speakStatus}
          className="p-3 rounded-full shadow-sm hover:scale-105 active:scale-95 transition-all"
          style={{ background: 'rgba(14,165,233,0.1)', color: '#0ea5e9' }}
          aria-label="Hear sync status"
        >
          <Volume2 size={20} />
        </button>
      </div>

      {/* Main Status Visual */}
      <Card className={`!p-6 border-2 text-center transition-all ${totalPending > 0 ? 'border-red-200 bg-red-50/50' : 'border-emerald-200 bg-emerald-50/50'}`}>
        <div className="flex justify-center mb-4 relative">
          {totalPending > 0 ? (
            <div className="relative">
              <CloudOff size={64} className="text-red-400 animate-pulse" />
              <div className="absolute -top-2 -right-2 bg-red-500 text-white text-xs font-black w-7 h-7 rounded-full flex items-center justify-center shadow-lg">
                {totalPending}
              </div>
            </div>
          ) : (
            <Cloud size={64} className="text-emerald-500" />
          )}
        </div>
        <h3 className={`font-black text-xl uppercase tracking-wide mb-1 ${totalPending > 0 ? 'text-red-700' : 'text-emerald-700'}`}>
          {totalPending > 0 ? t('sync.action_required') : t('sync.fully_synced')}
        </h3>
        <p className={`text-sm font-semibold ${totalPending > 0 ? 'text-red-500' : 'text-emerald-600'}`}>
          {totalPending > 0 ? t('sync.waiting_upload') : t('sync.all_saved')}
        </p>
      </Card>

      {/* Connection Status */}
      <Card className={`!p-4 border-2 ${isOnline ? 'border-blue-200 bg-blue-50/50' : 'border-amber-200 bg-amber-50/50'}`}>
        <div className="flex items-center gap-3">
          <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${isOnline ? 'bg-blue-100' : 'bg-amber-100'}`}>
            <Wifi size={20} className={isOnline ? 'text-blue-600' : 'text-amber-600'} />
          </div>
          <div>
            <p className={`font-bold text-sm ${isOnline ? 'text-blue-700' : 'text-amber-700'}`}>
              {isOnline ? t('sync.connected') : t('sync.no_internet')}
            </p>
            <p className="text-xs text-gray-400">
              {isOnline ? t('sync.ready_sync') : t('sync.will_sync_online')}
            </p>
          </div>
          <div className={`ml-auto w-2.5 h-2.5 rounded-full flex-shrink-0 ${isOnline ? 'bg-blue-500 animate-pulse' : 'bg-amber-400'}`} />
        </div>
      </Card>

      {/* Records Breakdown */}
      <Card>
        <div className="flex items-center gap-2 mb-4">
          <Database size={16} className="text-gray-400" />
          <h3 className="font-bold text-gray-700 text-sm">{t('sync.offline_records')}</h3>
          <button
            id="sync-refresh-btn"
            onClick={refreshPendingCount}
            className="ml-auto text-gray-300 hover:text-gray-500 transition-colors"
            aria-label="Refresh count"
          >
            <RefreshCw size={14} />
          </button>
        </div>

        <div className="space-y-2 mb-5">
          {[
            { label: t('sync.anemia_records'),  count: counts.anemia, color: '#0ea5e9' },
            { label: t('sync.ppd_screenings'),  count: counts.ppd,    color: '#8b5cf6' },
            { label: t('sync.panic_alerts'),    count: counts.alerts, color: '#ef4444' },
          ].map(({ label, count, color }) => (
            <div key={label} className="flex items-center justify-between py-2.5 border-b border-gray-50 last:border-0">
              <span className="text-sm font-semibold text-gray-600">{label}</span>
              <span
                className="text-sm font-black px-3 py-1 rounded-full"
                style={count > 0
                  ? { color, background: `${color}18`, border: `1px solid ${color}30` }
                  : { color: '#9ca3af', background: '#f9fafb' }
                }
              >
                {count}
              </span>
            </div>
          ))}
        </div>

        {/* Total Badge */}
        <div className={`flex items-center justify-between mb-5 p-3 rounded-2xl border ${totalPending > 0 ? 'bg-amber-50 border-amber-200' : 'bg-emerald-50 border-emerald-200'}`}>
          <span className={`text-sm font-bold ${totalPending > 0 ? 'text-amber-700' : 'text-emerald-700'}`}>
            {totalPending > 0 ? t('sync.pending', { count: totalPending }) : t('sync.all_synced')}
          </span>
          <span className={`text-2xl font-black ${totalPending > 0 ? 'text-amber-600' : 'text-emerald-600'}`}>
            {totalPending}
          </span>
        </div>

        {/* Sync Button */}
        <button
          id="sync-now-btn"
          onClick={handleSync}
          disabled={syncing || !isOnline}
          className="w-full btn-primary flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {syncing
            ? <><RefreshCw size={18} className="animate-spin" /> {t('sync.syncing')}</>
            : <><CloudUpload size={18} /> {t('sync.button')}</>
          }
        </button>

        {!isOnline && (
          <p className="text-center text-xs text-amber-600 font-semibold mt-3">
            {t('sync.connect_to_sync')}
          </p>
        )}

        {/* Status messages */}
        {status === 'success' && (
          <div className="flex items-center gap-2 p-3 bg-emerald-50 text-emerald-700 mt-4 rounded-xl text-sm font-semibold animate-slide-up">
            <CheckCircle size={18} /> {t('sync.success')}
          </div>
        )}
        {status === 'none' && (
          <div className="p-3 bg-blue-50 text-blue-700 mt-4 rounded-xl text-sm text-center font-semibold animate-slide-up">
            {t('sync.no_data')}
          </div>
        )}
        {status === 'error' && (
          <div className="flex items-center gap-2 p-3 bg-red-50 text-red-700 mt-4 rounded-xl text-sm font-semibold animate-slide-up">
            <AlertCircle size={18} /> {t('common.error')}
          </div>
        )}
      </Card>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Card } from '../components/Card';
import { getTasks, createTask, completeTask, type Task } from '../services/api';
import { CheckCircle, Circle, Plus, Calendar, Flag, Repeat, Mic, MicOff, ListChecks, Clock, MapPin, Map, Volume2, Zap } from 'lucide-react';
import { useVoiceRecognition } from '../hooks/useVoiceRecognition';
import { useTextToSpeech } from '../hooks/useTextToSpeech';
import { useTranslation } from 'react-i18next';

type Priority = 'high' | 'medium' | 'low' | 'all';

const PRIORITY_COLORS: Record<string, { border: string; bg: string; text: string; badge: string }> = {
  high:   { border: 'border-l-red-500',    bg: 'bg-red-50',     text: 'text-red-600',    badge: 'bg-red-50 text-red-600 border-red-200' },
  medium: { border: 'border-l-orange-400', bg: 'bg-orange-50',  text: 'text-orange-600', badge: 'bg-orange-50 text-orange-600 border-orange-200' },
  low:    { border: 'border-l-emerald-400',bg: 'bg-emerald-50', text: 'text-emerald-600',badge: 'bg-emerald-50 text-emerald-600 border-emerald-200' },
};

function getGreeting(): string {
  const h = new Date().getHours();
  if (h < 12) return 'morning';
  if (h < 17) return 'afternoon';
  return 'evening';
}

export const WorkloadManager: React.FC = () => {
  const { t } = useTranslation();
  const { speak } = useTextToSpeech();
  const [tasks, setTasks] = useState<Task[]>([]);
  const [loading, setLoading] = useState(true);
  const [showAdd, setShowAdd] = useState(false);
  const [showCompleted, setShowCompleted] = useState(false);
  const [filterPriority, setFilterPriority] = useState<Priority>('all');
  const [smartRoute, setSmartRoute] = useState(false);

  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [dueDate, setDueDate] = useState('');
  const [location, setLocation] = useState('');
  const [priority, setPriority] = useState<'high' | 'medium' | 'low'>('medium');
  const [isRecurring, setIsRecurring] = useState(false);

  const { listen, stop, isListening, transcript, clearTranscript } = useVoiceRecognition();

  const fetchTasks = useCallback(async () => {
    try {
      setLoading(true);
      const data = await getTasks(true);
      setTasks(data);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { fetchTasks(); }, [fetchTasks]);

  useEffect(() => {
    if (transcript && showAdd) {
      setTitle(transcript);
      speak(`${t('tasks.task_title')}: ${transcript}`);
      clearTranscript();
      stop();
    }
  }, [transcript, showAdd, stop, clearTranscript, speak, t]);

  // Voice greeting on mount
  useEffect(() => {
    const timer = setTimeout(() => {
      if (!loading) {
        const pending = tasks.filter(tk => !tk.completed).length;
        const greetKey = `greeting.${getGreeting()}`;
        speak(`${t(greetKey)}. ${t('greeting.voice_greeting', { count: pending })}`);
      }
    }, 800);
    return () => clearTimeout(timer);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loading]);

  const handleComplete = async (id: string) => {
    try {
      await completeTask(id);
      speak(t('tasks.complete'));
      fetchTasks();
    } catch (e) {
      console.error(e);
    }
  };

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) return;
    try {
      await createTask({ title, description, due_date: dueDate || undefined, location: location || undefined, priority, is_recurring: isRecurring });
      speak(`${t('tasks.add_btn')}: ${title}`);
      setTitle(''); setDescription(''); setDueDate(''); setLocation('');
      setPriority('medium'); setIsRecurring(false); setShowAdd(false);
      fetchTasks();
    } catch (e) {
      console.error(e);
    }
  };

  const pendingTasks = tasks.filter(tk => !tk.completed);
  const completedTasks = tasks.filter(tk => tk.completed);

  const visibleBase = showCompleted ? completedTasks : pendingTasks;
  const visibleTasks = filterPriority === 'all'
    ? visibleBase
    : visibleBase.filter(tk => tk.priority === filterPriority);

  const isOverdue = (due: string) => new Date(due) < new Date() && !!due;

  const today = new Date().toLocaleDateString(t('tabs.tasks') === 'Tasks' ? 'en-IN' : 'hi-IN', { weekday: 'long', day: 'numeric', month: 'long' });

  const greetKey = `greeting.${getGreeting()}`;

  const renderTaskCard = (task: Task, idx: number) => {
    const pc = PRIORITY_COLORS[task.priority] ?? PRIORITY_COLORS.medium;
    return (
      <Card
        key={task.id}
        className={`animate-slide-up stagger-${Math.min(idx + 1, 6)} cursor-pointer border-l-4 !pl-4 ${pc.border} ${task.completed ? 'opacity-60' : ''}`}
      >
        <div className="flex items-start gap-3">
          <button
            id={`task-complete-${task.id}`}
            onClick={() => handleComplete(task.id)}
            className="mt-0.5 flex-shrink-0"
            aria-label={t('tasks.complete')}
          >
            {task.completed
              ? <CheckCircle size={22} className="text-emerald-500" />
              : <Circle size={22} className="text-gray-300 hover:text-primary transition-colors" />
            }
          </button>
          <div className="flex-1 min-w-0">
            <div className="flex justify-between items-start gap-2 mb-1">
              <h4 className={`font-bold text-sm leading-tight ${task.completed ? 'line-through text-gray-400' : 'text-gray-800'}`}>
                {task.title}
              </h4>
              <span className={`text-[9px] uppercase px-2 py-0.5 rounded-full font-black flex-shrink-0 border ${pc.badge}`}>
                {t(`tasks.priority_${task.priority}`)}
              </span>
            </div>
            {task.description && <p className="text-xs text-gray-400 mb-2 line-clamp-2">{task.description}</p>}
            <div className="flex gap-3 flex-wrap items-center">
              {task.location && (
                <span className="flex items-center gap-1 text-[11px] font-semibold text-primary/80">
                  <MapPin size={10} /> {task.location}
                </span>
              )}
              {task.due_date && (
                <span className={`flex items-center gap-1 text-[11px] font-semibold ${isOverdue(task.due_date) && !task.completed ? 'text-red-500' : 'text-gray-400'}`}>
                  <Calendar size={10} />
                  {new Date(task.due_date).toLocaleDateString()}
                  {isOverdue(task.due_date) && !task.completed && ' ⚠'}
                </span>
              )}
              {task.is_recurring && (
                <span className="flex items-center gap-1 text-[11px] font-semibold text-blue-500">
                  <Repeat size={10} /> {t('tasks.recurring')}
                </span>
              )}
            </div>
          </div>
          <button
            onClick={() => speak(`${task.title}. ${task.description ?? ''} ${task.due_date ? t('tasks.due') + ': ' + new Date(task.due_date).toLocaleDateString() : ''}`)}
            className="p-1.5 rounded-full hover:bg-gray-100 text-gray-300 hover:text-primary transition-colors flex-shrink-0"
            aria-label="Read task aloud"
          >
            <Volume2 size={14} />
          </button>
        </div>
      </Card>
    );
  };

  return (
    <div className="space-y-4 pb-4 animate-fade-in">
      {/* Hero Greeting Card */}
      <div
        className="rounded-2xl p-5 text-white relative overflow-hidden shadow-lg"
        style={{ background: 'linear-gradient(135deg, #6367FF 0%, #8494FF 60%, #FF6B35 100%)' }}
      >
        {/* Decorative circle */}
        <div className="absolute -right-8 -top-8 w-32 h-32 rounded-full bg-white/10" />
        <div className="absolute -right-2 -bottom-10 w-24 h-24 rounded-full bg-white/5" />
        <div className="relative z-10">
          <p className="text-white/80 text-xs font-bold uppercase tracking-widest mb-1">{today}</p>
          <h2 className="text-xl font-black mb-1">
            {t(greetKey)}, <span className="text-white/90">{t('greeting.worker')}</span> 👋
          </h2>
          <p className="text-white/80 text-sm font-semibold">
            {pendingTasks.length > 0
              ? t('greeting.tasks_pending', { count: pendingTasks.length })
              : t('greeting.all_done')}
          </p>
        </div>
        <button
          onClick={() => speak(`${t(greetKey)}. ${t('greeting.voice_greeting', { count: pendingTasks.length })}`)}
          className="absolute top-4 right-4 w-9 h-9 rounded-full bg-white/20 flex items-center justify-center hover:bg-white/30 active:scale-95 transition-all"
          aria-label="Hear greeting"
        >
          <Volume2 size={16} className="text-white" />
        </button>
      </div>

      {/* Header row */}
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-extrabold text-gray-900">{t('tasks.title')}</h2>
          <p className="text-xs text-gray-400 font-medium">{t('tasks.subtitle')}</p>
        </div>
        <button
          id="add-task-btn"
          onClick={() => setShowAdd(!showAdd)}
          className="w-11 h-11 rounded-2xl shadow-lg flex items-center justify-center hover:scale-105 active:scale-95 transition-all"
          style={{ background: 'linear-gradient(135deg, #6367FF, #8494FF)', boxShadow: '0 4px 15px rgba(99,103,255,0.4)' }}
        >
          <Plus size={22} className="text-white" />
        </button>
      </div>

      {/* Summary Stats */}
      <div className="grid grid-cols-2 gap-3">
        <button
          onClick={() => setShowCompleted(false)}
          className={`rounded-2xl p-4 text-left border-2 transition-all ${!showCompleted ? 'border-primary bg-primary/5 shadow-sm' : 'border-gray-100 bg-white/60'}`}
        >
          <Clock size={20} className={`mb-2 ${!showCompleted ? 'text-primary' : 'text-gray-400'}`} />
          <p className={`text-3xl font-black ${!showCompleted ? 'text-primary' : 'text-gray-700'}`}>{pendingTasks.length}</p>
          <p className="text-xs font-semibold text-gray-500">{t('tasks.pending')}</p>
        </button>
        <button
          onClick={() => setShowCompleted(true)}
          className={`rounded-2xl p-4 text-left border-2 transition-all ${showCompleted ? 'border-emerald-500 bg-emerald-50' : 'border-gray-100 bg-white/60'}`}
        >
          <CheckCircle size={20} className={`mb-2 ${showCompleted ? 'text-emerald-500' : 'text-gray-400'}`} />
          <p className={`text-3xl font-black ${showCompleted ? 'text-emerald-500' : 'text-gray-700'}`}>{completedTasks.length}</p>
          <p className="text-xs font-semibold text-gray-500">{t('tasks.completed')}</p>
        </button>
      </div>

      {/* Add Task Form */}
      {showAdd && (
        <Card className="border-2 border-primary/20 bg-blue-50/30 animate-slide-up">
          <form onSubmit={handleAdd} className="space-y-3">
            <div className="flex justify-between items-center mb-1">
              <h3 className="font-bold text-gray-800">{t('tasks.add_title')}</h3>
              <button
                type="button"
                onClick={isListening ? stop : listen}
                className={isListening ? 'btn-voice-active' : 'btn-voice-idle'}
                style={{ padding: '8px' }}
                aria-label={t('tasks.voice_add')}
              >
                {isListening
                  ? <div className="voice-wave"><span/><span/><span/><span/><span/></div>
                  : <Mic size={16} className="text-white" />
                }
              </button>
            </div>
            {isListening && (
              <div className="voice-hint text-xs animate-fade-in">
                🎤 {t('tasks.voice_add')}
              </div>
            )}
            <input
              autoFocus type="text" placeholder={t('tasks.task_title')} value={title}
              onChange={e => setTitle(e.target.value)}
              className="input-field" required
            />
            <textarea
              placeholder={t('tasks.description')} value={description}
              onChange={e => setDescription(e.target.value)}
              className="input-field resize-none" rows={2}
            />
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="text-xs font-bold text-gray-500 mb-1 flex items-center gap-1"><Calendar size={11} /> {t('tasks.due_date')}</label>
                <input type="date" value={dueDate} onChange={e => setDueDate(e.target.value)} className="input-field text-sm" />
              </div>
              <div>
                <label className="text-xs font-bold text-gray-500 mb-1 flex items-center gap-1"><Flag size={11} /> {t('tasks.priority')}</label>
                <select value={priority} onChange={e => setPriority(e.target.value as any)} className="input-field text-sm bg-white">
                  <option value="low">{t('tasks.priority_low')}</option>
                  <option value="medium">{t('tasks.priority_medium')}</option>
                  <option value="high">{t('tasks.priority_high')}</option>
                </select>
              </div>
              <div className="col-span-2">
                <label className="text-xs font-bold text-gray-500 mb-1 flex items-center gap-1"><MapPin size={11} /> {t('tasks.location')}</label>
                <input type="text" placeholder="e.g. Village Rampur" value={location} onChange={e => setLocation(e.target.value)} className="input-field text-sm" />
              </div>
            </div>
            <label className="flex items-center gap-2 text-sm font-medium cursor-pointer py-1">
              <input type="checkbox" checked={isRecurring} onChange={e => setIsRecurring(e.target.checked)} className="w-4 h-4 accent-primary rounded" />
              <Repeat size={14} className="text-gray-500" /> {t('tasks.recurring')}
            </label>
            <div className="grid grid-cols-2 gap-2 pt-1">
              <button type="button" onClick={() => setShowAdd(false)} className="py-2.5 rounded-xl font-bold text-gray-600 bg-gray-100 hover:bg-gray-200 transition-all active:scale-95">
                {t('tasks.cancel')}
              </button>
              <button type="submit" className="btn-primary py-2.5">{t('tasks.add_btn')}</button>
            </div>
          </form>
        </Card>
      )}

      {/* Priority filter chips + Smart Route */}
      <div className="flex items-center gap-2 overflow-x-auto scrollbar-none pb-1">
        {(['all', 'high', 'medium', 'low'] as Priority[]).map(p => (
          <button
            key={p}
            onClick={() => setFilterPriority(p)}
            className={filterPriority === p ? 'chip-active flex-shrink-0' : 'chip-inactive flex-shrink-0'}
          >
            {p === 'all' ? t('tasks.filter_all') : t(`tasks.priority_${p}`)}
          </button>
        ))}
        <div className="flex-1" />
        {!showCompleted && visibleBase.length > 0 && (
          <button
            onClick={() => setSmartRoute(v => !v)}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-black border flex-shrink-0 transition-all ${smartRoute ? 'bg-primary text-white border-primary shadow-sm' : 'bg-white text-gray-500 border-gray-200'}`}
          >
            <Map size={12} /> {t('tasks.smart_route')}
          </button>
        )}
      </div>

      {/* Section label */}
      <div className="flex items-center gap-2">
        <ListChecks size={14} className="text-gray-400" />
        <p className="section-label">
          {showCompleted ? t('tasks.completed_tasks') : t('tasks.pending_tasks_label')}
          <span className="text-primary ml-1 font-black">({visibleTasks.length})</span>
        </p>
      </div>

      {/* Scientific tip */}
      {!showCompleted && (
        <div className="sci-ref-card flex items-start gap-3">
          <Zap size={16} className="text-primary flex-shrink-0 mt-0.5" />
          <p className="text-xs text-gray-600 font-medium leading-relaxed">{t('tasks.scientific_tip')}</p>
        </div>
      )}

      {/* Task List */}
      {loading ? (
        <div className="space-y-3">
          {[1, 2, 3].map(i => (
            <div key={i} className="card h-20 shimmer-bg rounded-2xl" />
          ))}
        </div>
      ) : visibleTasks.length === 0 ? (
        <Card className="text-center py-10">
          <ListChecks size={40} className="mx-auto text-gray-200 mb-3" />
          <p className="text-gray-400 font-semibold text-sm">
            {showCompleted ? t('tasks.no_completed') : t('tasks.no_tasks')}
          </p>
        </Card>
      ) : (
        <div className="space-y-3">
          {smartRoute && !showCompleted ? (
            Object.entries(
              visibleTasks.reduce((acc, task) => {
                const loc = task.location || 'Unspecified Location';
                if (!acc[loc]) acc[loc] = [];
                acc[loc].push(task);
                return acc;
              }, {} as Record<string, Task[]>)
            ).map(([loc, locTasks], gi) => (
              <div key={loc} className={`animate-slide-up stagger-${Math.min(gi + 1, 4)}`}>
                <h3 className="section-label mb-2">
                  <MapPin size={12} className="text-primary" />
                  {loc} <span className="text-primary ml-1">({locTasks.length})</span>
                </h3>
                <div className="space-y-2">
                  {locTasks.map((task, idx) => renderTaskCard(task, idx))}
                </div>
              </div>
            ))
          ) : (
            visibleTasks.map((task, idx) => renderTaskCard(task, idx))
          )}
        </div>
      )}
    </div>
  );
};
